#include "taskManage/TaskNode.h"
#include <cstddef>
#include <string>

class TestGenerateRandomWorkFlowID: public ::testing::Test
{
protected:
   static void SetUpTestCase()
   {
   }

   static void TearDownTestCase()
   {
   }

   virtual void SetUp()
   {
   }

   virtual void TearDown()
   {
       GlobalMockObject::verify();
   }
};

TEST_F(TestGenerateRandomWorkFlowID, ut_name) {

    // When
    std::string result = WorkFlow::generateRandomWorkFlowID();

    // Then
    EXPECT_EQ(result.length(), 8);
    for (char c: result) {
        EXPECT_TRUE(c >= '0' && c <= '9');
    }
}
